using System.Security.Cryptography;
using SixLabors.ImageSharp.Formats.Av1;
using SixLabors.ImageSharp.Formats.Av1.Bitstream;

namespace SixLabors.ImageSharp.Codecs.Av1.Tests;

/// <summary>
/// Validates wedge-masked compound prediction on a 24-frame 128x128 aomenc two-pass clip encoded at a
/// speed setting that selects wedge blends: the wedge masks are built from the six 64x64 master
/// templates exactly as the reference decoder does, and compound blocks blend their two intermediates
/// by the selected wedge shape (with sign-aware chroma subsampling of the mask). Every displayed frame
/// must be exactly equal to dav1d's output, verified by per-frame SHA-256 digests.
/// </summary>
public class Av1WedgeCompoundDecodeTests
{
    private const string ClipIvfBase64 =
        "";

    private static readonly string[] FrameDigests = [
        "15103ca00ac0790468653fb0e037ea42e4146ade40bd3992c784a6293979874e",
        "7915b7da50cf1571748c76352fd83c9bda8f021f6d9f4cbde9339437bbe70fc1",
        "25e50fda1b7140673bc95d9882035ef9049b843160d2cad1b6c0601387e4d3b9",
        "c5e97eb568a4028e13a2b15f1c085209e06eef6db2c098e96902c3928fc6a957",
        "051eccb10513882ad57d4c93d78e4c3ffe3cf7bb083d1379d2dee787edd07ed9",
        "95b5176edf06ff82564b9cc8490b95bd88d706262702db28af5c844edaa6de89",
        "fd44cfd7b6a023d09614c14e6b20f38744200d73134ca0612af83a0cb90a8073",
        "0a1c175c9bfd982ae4d45d40f73a38d3359e2f5bf7de293b48ec70bf141c79bc",
        "2e22edfaad6b6174cac7482b950b3d7308954586ef20250112a68284edaaa5ee",
        "b41b8f74faefc7fb7c0ab190ac5b9876d25659478434f1aaba5145fdb1ef9213",
        "8c3c97de295c8ced5116b25ec9f70f91bf3b34b2deffb3d10cf26080b2841c5b",
        "2517935b8754f6e5d5f9a0fa203cd3b9de759d2851d699047896cfb8f6f65474",
        "90d04fc81517c96c02df0abc66f38a210f0f7e024d6e090b77d49d2cd7447f41",
        "18a31e718fd3044b76c49464766c26fe43e4660e024ae769966b5e957f1f7f73",
        "83317f515d8cfd58c0eeb4cf651326039be0f0e9b84bd79ceeb5196f5c32c23c",
        "e8a506357f53ea86bd455511dd39fc41bc148ac3183c44febed01fdc6d7f8b5a",
        "2dd1679d4367c38db766ced3715bbbc35679751248afe088083fc14852b26c88",
        "536e627d9efb1c82e6b7eb5ab3c7f1e338a097f514b5c4c165372fe1a0c7bb75",
        "a762d4c49aa3ea0f34dab403173fceb2629dbd83d89075638f96fd2e0a2a02c5",
        "d477a45b3243c8e207d9be4f41c4d741f06c025f4d6ca0357ffe2937c5ae5823",
        "9dca493fc2426bd8b2a19e46a24799187c5823f915bb404c4b3985616e0b888c",
        "84e8ebc8c4985104657d3b6685298e9a305b5a674e93f6e31ba0b6e41fa30273",
        "e312cf438c3ce3a0b92a479cb47a3528524d0ad6a1ff43bbba694409b64158ed",
        "ca8c1ada2f536553aac5a6666607862fae78aeafe97be71f24a271bb0a1b0994",
    ];

    [Fact]
    public void DecodeDisplayFrames_WedgeCompoundClip_MatchesDav1dExactly()
    {
        using MemoryStream stream = new(Convert.FromBase64String(ClipIvfBase64));
        List<Av1DisplayFrame> frames = Av1DecoderCore.DecodeDisplayFrames(stream);

        Assert.Equal(FrameDigests.Length, frames.Count);
        for (int i = 0; i < frames.Count; i++)
        {
            using IncrementalHash hash = IncrementalHash.CreateHash(HashAlgorithmName.SHA256);
            AppendCropped(hash, frames[i].Luma);
            AppendCropped(hash, frames[i].ChromaU);
            AppendCropped(hash, frames[i].ChromaV);
            string digest = Convert.ToHexString(hash.GetHashAndReset()).ToLowerInvariant();
            Assert.True(FrameDigests[i] == digest, $"frame {i}: plane digest mismatch");
        }
    }

    private static void AppendCropped(IncrementalHash hash, Av1Plane plane)
    {
        for (int y = 0; y < plane.CropHeight; y++)
        {
            hash.AppendData(plane.Samples, y * plane.Width, plane.CropWidth);
        }
    }
}
